INSERT INTO ref.band VALUES
	('level', -1000, 'normal', 2, NULL, 'within or below its typical range'),
	('level', 0, 'elevated', 3, NULL, 'above its typical range'),
	('level', 0.5, 'high', 4, NULL, 'more than halfway from typical high to the highest level on record'),
	('level', 0.9, 'severe', 5, NULL, 'within 10% of the highest level on record, or above it'),
	('flow', -1000, 'normal', 2, NULL, 'under 30% of the median annual flood (QMED)'),
	('flow', 0.3, 'elevated', 3, NULL, '30-70% of the median annual flood'),
	('flow', 0.7, 'high', 4, NULL, '70-100% of the median annual flood'),
	('flow', 1.0, 'severe', 5, NULL, 'above the median annual flood (roughly a 1-in-2-year flow or worse)'),
	('flow_pct', 0, 'much_lower', 1, 'much lower than normal', NULL),
	('flow_pct', 10, 'lower', 2, 'lower than normal', NULL),
	('flow_pct', 30, 'normal', 3, 'about normal', NULL),
	('flow_pct', 70, 'higher', 4, 'higher than normal', NULL),
	('flow_pct', 90, 'much_higher', 5, 'much higher than normal', NULL) ON CONFLICT DO NOTHING;
