INSERT INTO ref.signal VALUES
	('chemical', 'Chemical', 'chemical', 'WFD physico-chemical + chemical status and the latest official nutrient/oxygen readings.', '{good,moderate,poor,bad}', 1, false),
	('ecological', 'Ecological', 'ecology', 'WFD ecological and biological classes, Riverfly scores, obstacles.', '{good,moderate,poor,bad}', 2, false),
	('sewage_pressure', 'Sewage pressure', 'sewage', 'Storm overflow activity, consented discharges and modelled sewage load upstream and in the waterbody.', '{low,moderate,high,dominant}', 3, true),
	('agricultural_pressure', 'Agricultural pressure', 'farming', 'Modelled agricultural share of nutrient load, official reasons-for-failure, nutrient neutrality status. Inferred landscape risk, never field attribution.', '{low,moderate,high,dominant}', 4, true),
	('algal_visual', 'Algal / visual', 'algae', 'Citizen reports of colour, algae and turbidity; satellite true-colour when available.', '{good,moderate,poor,bad}', 5, false),
	('flow', 'Flow', 'flow', 'River flow now against that river''s own long-term record, from the nearest gauge on the same river.', '{"much lower than normal","lower than normal","about normal","higher than normal","much higher than normal"}', 6, false) ON CONFLICT DO NOTHING;
